annex_sha='b04b50c87e227498a7acf48dec0a8a46e3e2288bb09045f479c9de2523a1d617'
if sha(annex)!=annex_sha:raise RuntimeError('Previous annex payload changed')
plan=[('full','S11c_d_mixing_scattering_sympy_audit.out','459c047acee94c5f307bd914809747954d4fb2b2d46bc36c78ace8e1b500e6c2'),('reference_final_v3','S11c_d_threshold_modes_reference.out',None),('left_final','S11c_d_threshold_modes_left.out',None),('right_final','S11c_d_threshold_modes_right.out',None)]
