 checked.append((stage,src,dest,digest,previous,dest.is_symlink()))
records=[]
for stage,src,dest,digest,previous,was_link in checked:
 fd,temp=tempfile.mkstemp(prefix='.'+dest.name+'.',suffix='.tmp',dir=dest.parent)
 try:
  with os.fdopen(fd,'wb') as out,src.open('rb') as source:
   shutil.copyfileobj(source,out,1048576);out.flush();os.fsync(out.fileno())
  os.chmod(temp,0o644)
  if sha(pathlib.Path(temp))!=digest:raise RuntimeError('Copy digest mismatch')
  os.replace(temp,dest)
 finally:
  if os.path.lexists(temp):os.unlink(temp)
 if sha(dest)!=digest:raise RuntimeError('Published digest mismatch')
 records.append({'stage':stage,'source':str(src),'published':str(dest),'bytes':dest.stat().st_size,'sha256':digest,'previousSha256':previous,'replacedSymlink':was_link,'publishedIsSymlink':dest.is_symlink()})
